def migrate_sector_to_fk(apps, schema_editor):
    """
    Convert legacy MembershipApplication.sector text values
    into foreign keys to organizations.Sector.
    """
    Application = apps.get_model(
        "memberships", "MembershipApplication"
    )
    Sector = apps.get_model("organizations", "Sector")
    db = schema_editor.connection.alias

    sectors = list(Sector.objects.using(db).all())

    sector_lookup = {}

    for sector in sectors:
        sector_lookup[sector.name.strip().casefold()] = sector.pk
        sector_lookup[sector.slug.strip().casefold()] = sector.pk

    # Legacy "Informatique" values map to this existing sector.
    digital_sector = next(
        (
            sector
            for sector in sectors
            if sector.slug == "numerique-et-telecoms"
        ),
        None,
    )

    if digital_sector is not None:
        sector_lookup["informatique"] = digital_sector.pk

    applications = list(
        Application.objects.using(db).values_list("pk", "sector")
    )

    updates = []
    unknown = set()

    for application_id, value in applications:
        value = (value or "").strip()

        if not value:
            continue

        sector_id = sector_lookup.get(value.casefold())

        if sector_id is None:
            unknown.add(value)
        else:
            updates.append((application_id, sector_id))

    if unknown:
        raise RuntimeError(
            "Cannot map existing membership sector values: "
            + ", ".join(sorted(unknown))
            + ". Existing data has not been intentionally discarded."
        )

    for application_id, sector_id in updates:
        Application.objects.using(db).filter(
            pk=application_id
        ).update(sector_new_id=sector_id)


def reverse_sector_migration(apps, schema_editor):
    """
    Restore the legacy text field if this migration is reversed.
    """
    Application = apps.get_model(
        "memberships", "MembershipApplication"
    )
    Sector = apps.get_model("organizations", "Sector")
    db = schema_editor.connection.alias

    sectors = {
        sector.pk: sector
        for sector in Sector.objects.using(db).all()
    }

    applications = (
        Application.objects.using(db)
        .filter(sector_new_id__isnull=False)
        .values_list("pk", "sector_new_id")
    )

    for application_id, sector_id in applications:
        sector = sectors[sector_id]

        legacy_value = (
            "Informatique"
            if sector.slug == "numerique-et-telecoms"
            else sector.name
        )

        Application.objects.using(db).filter(
            pk=application_id
        ).update(sector=legacy_value)


